-- Global Terminal v3. Apply after review in Supabase SQL editor.
create extension if not exists pgcrypto;
create table if not exists public.instruments (
 id text primary key, symbol text not null, display_symbol text not null, name text not null,
 asset_class text not null check(asset_class in ('crypto','stock','etf','index','fx','commodity')),
 exchange text not null, mic text, country text, currency text not null, quote_currency text,
 provider_symbols jsonb not null default '{}', timezone text not null default 'UTC', trading_calendar text not null default '24/7',
 tick_size numeric not null default .01, lot_size numeric not null default 1, price_precision int not null default 2,
 isin text, figi text, active boolean not null default true, data_capabilities text[] not null default '{}');
create index if not exists instruments_search_idx on public.instruments using gin(to_tsvector('simple',symbol||' '||name));
create table if not exists public.candles (
 instrument_id text references public.instruments(id), timeframe text not null, open_time timestamptz not null,
 open numeric not null, high numeric not null, low numeric not null, close numeric not null, volume numeric not null,
 source text not null, ingested_at timestamptz not null default now(), adjusted boolean not null default false,
 quality_flags text[] not null default '{}', primary key(instrument_id,timeframe,open_time));
create table if not exists public.user_preferences(user_id uuid primary key references auth.users(id) on delete cascade,locale text not null default 'tr',timezone text not null default 'Europe/Istanbul',base_currency text not null default 'TRY',updated_at timestamptz not null default now());
create table if not exists public.watchlists(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,created_at timestamptz not null default now());
create table if not exists public.watchlist_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,watchlist_id uuid not null references public.watchlists(id) on delete cascade,instrument_id text not null references public.instruments(id),position int not null default 0,unique(watchlist_id,instrument_id));
create table if not exists public.paper_accounts(id text primary key,user_id uuid not null references auth.users(id) on delete cascade,name text not null,base_currency text not null,starting_cash numeric not null,cash_balance numeric not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.paper_orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id text not null,instrument_id text not null references public.instruments(id),side text not null,order_type text not null,quantity numeric not null check(quantity>0),limit_price numeric,stop_price numeric,status text not null,filled_quantity numeric not null default 0,fill_price numeric,commission numeric not null default 0,realized_pnl numeric,parent_id uuid,oco_group uuid,rejection_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.paper_orders add column if not exists parent_id uuid;
alter table public.paper_orders add column if not exists oco_group uuid;
alter table public.paper_orders add column if not exists mae numeric;
alter table public.paper_orders add column if not exists mfe numeric;
create table if not exists public.paper_fills(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id text not null,order_id uuid not null references public.paper_orders(id),instrument_id text not null references public.instruments(id),side text not null,quantity numeric not null,price numeric not null,commission numeric not null default 0,filled_at timestamptz not null default now());
create table if not exists public.cash_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id text not null,currency text not null,amount numeric not null,event_type text not null,reference_id uuid,created_at timestamptz not null default now());
create table if not exists public.audit_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,event_type text not null,entity_id text,payload jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.paper_positions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id text not null,instrument_id text not null references public.instruments(id),quantity numeric not null,average_price numeric not null,updated_at timestamptz not null default now(),unique(account_id,instrument_id));
create table if not exists public.alerts_v3(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,instrument_id text not null references public.instruments(id),field text not null,operator text not null,target numeric not null,state text not null default 'armed',cooldown_seconds int not null default 300,last_value numeric,last_triggered_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.alert_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,alert_id uuid not null references public.alerts_v3(id) on delete cascade,instrument_id text not null references public.instruments(id),field text not null,value numeric,target numeric,triggered_at timestamptz not null default now());
create table if not exists public.research_notes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,instrument_id text not null references public.instruments(id),order_id uuid,title text not null,thesis text not null default '',strategy text,tags text[] not null default '{}',planned_risk numeric,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.research_notes add column if not exists planned_reward numeric;
alter table public.research_notes add column if not exists realized_r numeric;
alter table public.research_notes add column if not exists mae numeric;
alter table public.research_notes add column if not exists mfe numeric;
alter table public.research_notes add column if not exists rule_violations text[] not null default '{}';
alter table public.research_notes add column if not exists before_image_url text;
alter table public.research_notes add column if not exists after_image_url text;
create table if not exists public.portfolios(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,base_currency text not null default 'USD',created_at timestamptz not null default now());
create table if not exists public.portfolio_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,portfolio_id uuid references public.portfolios(id) on delete cascade,instrument_id text not null references public.instruments(id),side text not null,quantity numeric not null,price numeric not null,fees numeric not null default 0,currency text not null,executed_at timestamptz not null,created_at timestamptz not null default now());
create table if not exists public.position_snapshots(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,portfolio_id uuid references public.portfolios(id) on delete cascade,base_currency text not null,total_value numeric not null,external_flow numeric not null default 0,positions jsonb not null default '[]',as_of timestamptz not null default now());
create table if not exists public.saved_screens(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,filters jsonb not null default '{}',sort text not null default 'change_pct',direction text not null default 'desc',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.workspace_layouts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,layout jsonb not null,is_default boolean not null default false,updated_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['user_preferences','watchlists','watchlist_items','paper_accounts','paper_orders','paper_fills','paper_positions','cash_ledger','alerts_v3','alert_events','research_notes','portfolios','portfolio_transactions','position_snapshots','saved_screens','workspace_layouts','audit_events'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists owner_all on public.%I',t); execute format('create policy owner_all on public.%I for all using (auth.uid()=user_id) with check (auth.uid()=user_id)',t); end loop; end $$;
